// JAH demo program — Finding strength
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function strength(n, peerReviewed, replicated){ var s=0; if(n>1000)s++; if(peerReviewed)s++; if(replicated)s+=2; return s; }
check("large + peer + replicated = 4", strength(30000,true,true), 4);
check("small, unreviewed = 0", strength(20,false,false), 0);
check("peer only = 2", strength(500,true,false), 1);
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

